function showAfterScene(index){const root=main.querySelector('.after-hours');if(!root)return;const scenes=[...root.querySelectorAll('[data-after-scene]')];const next=(index+scenes.length)%scenes.length;scenes.forEach((scene,i)=>{scene.hidden=i!==next;scene.classList.toggle('is-active',i===next)});root.querySelectorAll('[data-after-go]').forEach((button,i)=>button.setAttribute('aria-current',String(i===next)));root.querySelector('.after-count').textContent=String(next+1).padStart(2,'0')+' / 06';const thumbs=[['content','camera-photo.webp'],['music','record-deck-photo.webp'],['films','tv-photo.webp'],['dance','dance-boombox.webp'],['books','books-v3-photo.webp'],['trails','trail-map-photo.webp']];for(const [direction,offset] of [['prev',-1],['next',1]]){const [label,asset]=thumbs[(next+offset+thumbs.length)%thumbs.length];const peek=root.querySelector('.after-peek-'+direction);peek.querySelector('img').src='objects/'+asset;peek.classList.toggle('is-music',label==='music');peek.setAttribute('aria-label',(offset<0?'Previous: ':'Next: ')+label)}updateTvClip(next===2);const scene=scenes[next];if(!matchMedia('(prefers-reduced-motion: reduce)').matches)scene.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,easing:'cubic-bezier(.2,.8,.2,1)'});}
