main.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.camera-back')){e.preventDefault();turnCamera(e.target.closest('.camera-object'),false)}});
function turnCamera(obj,toBack){
  if(obj._flashTimer)return;
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    obj.classList.toggle('is-flipped',toBack);
    obj.querySelector('.camera-front').hidden=toBack;
    obj.querySelector('.camera-back').hidden=!toBack;
    obj.querySelector('.camera-front').setAttribute('aria-expanded',String(toBack));
    return;
  }
  const popup=obj.closest('.camera-popup');
  obj.classList.remove('is-flashing');
  void obj.offsetWidth;
  obj.classList.add('is-flashing');
  if(popup){popup.classList.remove('is-transitioning');void popup.offsetWidth;popup.classList.add('is-transitioning')}
  setTimeout(()=>obj.classList.add('is-concealing'),140);
  obj._flashTimer=setTimeout(()=>{
    obj.classList.toggle('is-flipped',toBack);
    obj.querySelector('.camera-front').hidden=toBack;
    obj.querySelector('.camera-back').hidden=!toBack;
    obj.querySelector('.camera-front').setAttribute('aria-expanded',String(toBack));
    obj._flashTimer=null;
  },240);
  setTimeout(()=>obj.classList.remove('is-concealing'),440);
  setTimeout(()=>{obj.classList.remove('is-flashing');popup?.classList.remove('is-transitioning')},650);
}
function openCamera(){
  if(document.querySelector('.camera-popup[open]'))return;
  const source=main.querySelector('.after-camera .camera-object');
  if(!source)return;
  const dialog=document.createElement('dialog');
  dialog.className='content-popup camera-popup after-camera';
  dialog.setAttribute('aria-label','Stephanie’s camera and social profiles');
  dialog.innerHTML='<button type="button" class="content-close" aria-label="Close camera">×</button>';
  const camera=source.cloneNode(true);
  dialog.append(camera);
  document.body.append(dialog);
  const closeCamera=()=>{
    if(dialog._closing)return;
    dialog._closing=true;
    if(dialog.open)dialog.close();
  };
  dialog.querySelector('.content-close').addEventListener('click',closeCamera);
  dialog.addEventListener('click',e=>{
    if(e.target===dialog){closeCamera();return}
    if(e.target.closest('.camera-profiles a'))return;
    if(e.target.closest('.camera-back'))closeCamera();
  });
  dialog.addEventListener('keydown',e=>{
    if((e.key==='Enter'||e.key===' ')&&e.target.matches('.camera-back')){
      e.preventDefault();closeCamera()
    }
  });
  dialog.addEventListener('cancel',e=>{e.preventDefault();closeCamera()});
  dialog.addEventListener('close',()=>{dialog.remove();source.querySelector('.camera-front')?.focus()},{once:true});
  dialog.showModal();
  turnCamera(camera,true);
}
function openReadingBook(source){
  if(document.querySelector('.books-popup[open]'))return;
  const dialog=document.createElement('dialog');
  dialog.className='content-popup books-popup';
  dialog.setAttribute('aria-label','My reading picks');
  const stage=source.querySelector('.open-book').cloneNode(true);
  stage.classList.remove('book-inline-stage');
  dialog.innerHTML='<button type="button" class="content-close" aria-label="Close book">×</button>';
  dialog.append(stage);
  document.body.append(dialog);
  const notes=dialog.querySelector('.book-notes');
  const reveal=()=>{if(dialog.open){notes.classList.add('is-open');notes.setAttribute('aria-hidden','false')}};
  dialog.querySelector('.book-leaf').addEventListener('animationend',reveal,{once:true});
  const timer=setTimeout(reveal,1450);
  dialog.querySelector('.content-close').addEventListener('click',()=>dialog.close());
  dialog.addEventListener('close',()=>{clearTimeout(timer);dialog.remove();source.querySelector('.books-open').setAttribute('aria-expanded','false');source.querySelector('.books-open').focus()},{once:true});
  source.querySelector('.books-open').setAttribute('aria-expanded','true');
  dialog.showModal();
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)reveal();
}
main.addEventListener('click',e=>{
  if(e.target.closest('.camera-open')){openCamera();return}
  if(e.target.closest('.books-open')){const obj=main.querySelector('.book-object');if(obj)openReadingBook(obj);return}
  if(e.target.closest('.dance-open')){const radio=main.querySelector('.dance-radio');const playing=radio.classList.toggle('is-playing');radio.setAttribute('aria-pressed',String(playing));radio.setAttribute('aria-label',playing?'Pause dance break':'Start a dance break');return}
  if(e.target.closest('.record-pop-close')){main.querySelector('.after-record .tonearm')?.click();return}
  if(e.target.closest('.tonearm,.record-skip')){const scene=main.querySelector('.after-record');if(!scene)return;const player=scene.querySelector('.record-player');const open=player.hidden;player.hidden=!open;const embed=player.querySelector('iframe');if(open){embed.src=embed.dataset.src||embed.src}else{embed.dataset.src=embed.src;embed.src='about:blank'}scene.querySelector('.mini-turntable').classList.toggle('needle-down',open);scene.querySelector('.tonearm').setAttribute('aria-pressed',String(open));scene.querySelector('.tonearm').setAttribute('aria-label',open?'Lift needle and close playlist':'Drop needle and open playlist');scene.querySelector('.record-skip').setAttribute('aria-expanded',String(open));scene.querySelector('.record-message').textContent=open?'Use Spotify in the corner to play or skip.':'Drop the needle to open my playlist.';return}
});

function writeBookNotes(dialog){
  const notes=dialog.querySelector('.book-notes');
  const lines=[...dialog.querySelectorAll('.book-writing')];
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const timers=[];
  let revealed=false;
  dialog.addEventListener('close',()=>timers.forEach(clearTimeout),{once:true});
  function reveal(){
    if(revealed||!dialog.open)return;
    revealed=true;
    notes.classList.add('is-open');
    notes.removeAttribute('aria-hidden');
    if(reduced){lines.forEach(line=>line.textContent=line.dataset.write);return}
    const headings=lines.filter(line=>line.tagName==='H3');
    const titleStart=240+Math.max(...headings.map(line=>line.dataset.write.length))*42+180;
    lines.forEach(line=>{
      const content=line.dataset.write;
      const offset=line.tagName==='H3'?240:titleStart;
      for(let index=0;index<content.length;index++){
        timers.push(setTimeout(()=>{
          if(!dialog.open)return;
          line.textContent=content.slice(0,index+1);
          line.classList.toggle('is-writing',index!==content.length-1);
        },offset+index*42));
      }
    });
  }
  if(reduced){reveal();return}
  const leaf=dialog.querySelector('.book-leaf');
  leaf.addEventListener('animationend',event=>{if(event.target===leaf&&event.animationName==='turn-reading-leaf')reveal()},{once:true});
  timers.push(setTimeout(reveal,1600));
}
